async function fetchTelemetry(endpoint: string, retries = 3): Promise<Response> {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      return await fetch(endpoint);
    } catch (err) {
      if (attempt === retries) throw err;
    }
  }
  throw new Error('Unreachable');
}
